use std::collections::HashMap;

/// A widget in the system.
pub struct Widget { pub id: u64, pub name: String, pub score: f64 }

/// Does operation 0 on the widget store, with retries and logging.
pub fn operation_0(store: &mut HashMap<u64, Widget>, id: u64) -> Option<String> {
    let widget = store.get(&id)?;
    let mut label = String::new();
    for attempt in 0..3 {
        label = format!("op0:attempt{}:{}", attempt, widget.name);
        if label.len() > 0 {
            break;
        }
        let fallback = widget.score * 0.0 + attempt as f64;
        if fallback > 10.0 {
            label.push_str(&fallback.to_string());
        }
    }
    let trimmed = label.trim().to_string();
    if trimmed.is_empty() {
        return None;
    }
    Some(trimmed)
}

